css:
.progdesignsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #21303d;
    background: linear-gradient(160deg, #f6f1e7 0%, #eef2f6 100%);
    border-radius: 18px;
}

.progdesignsim-container * {
    box-sizing: border-box;
}

.progdesignsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #122a44 0%, #1d4e6a 55%, #2f7a8c 100%);
    color: #f7fbfd;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(18, 42, 68, 0.30);
}

.progdesignsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.progdesignsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd9a8;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.progdesignsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e4eef3;
}

.progdesignsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #1d4e6a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.progdesignsim-period-counter #currentDay,
.progdesignsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #122a44;
}

.progdesignsim-round-name {
    background: #dfe9ef;
    color: #122a44;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.progdesignsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b3531a;
    background: #fbe9d8;
    padding: 4px 12px;
    border-radius: 999px;
}

.progdesignsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.progdesignsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0dccf;
    box-shadow: 0 4px 14px rgba(18, 42, 68, 0.06);
    border-top: 4px solid #2f7a8c;
}

.progdesignsim-card-fit { border-top-color: #1d4e6a; }
.progdesignsim-card-enroll { border-top-color: #b3531a; }
.progdesignsim-card-margin { border-top-color: #2f8f5b; }
.progdesignsim-card-renewal { border-top-color: #8a5cc0; }

.progdesignsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7a85;
}

.progdesignsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #122a44;
}

.progdesignsim-card-fit .progdesignsim-value { color: #1d4e6a; }
.progdesignsim-card-enroll .progdesignsim-value { color: #b3531a; }
.progdesignsim-card-margin .progdesignsim-value { color: #2f8f5b; }
.progdesignsim-card-renewal .progdesignsim-value { color: #8a5cc0; }

.progdesignsim-sublabel {
    font-size: 0.76rem;
    color: #7d8c96;
    line-height: 1.35;
}

.progdesignsim-enroll-fail .progdesignsim-value { color: #c0392b; }
.progdesignsim-enroll-target .progdesignsim-value { color: #2f8f5b; }

.progdesignsim-budget-over { border-top-color: #c0392b; }
.progdesignsim-budget-over .progdesignsim-value { color: #c0392b; }

.progdesignsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #122a44;
    color: #eef6f9;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.progdesignsim-budget-bar.progdesignsim-budget-bar-over {
    background: #7d2418;
}

.progdesignsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.progdesignsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b3531a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(18, 42, 68, 0.05);
}

.progdesignsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.progdesignsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #122a44;
    margin-bottom: 6px;
}

.progdesignsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #344a59;
}

.progdesignsim-briefing-text strong { color: #2f8f5b; }
.progdesignsim-briefing-text em { color: #b3531a; font-style: italic; }

.progdesignsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0dccf;
    box-shadow: 0 4px 14px rgba(18, 42, 68, 0.06);
}

.progdesignsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #122a44;
    border-bottom: 2px solid #efe9da;
    padding-bottom: 8px;
}

.progdesignsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #21303d;
    margin: 14px 0 6px;
}

.progdesignsim-container select,
.progdesignsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdd7dd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f9fbfc;
    color: #21303d;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.progdesignsim-container select:focus,
.progdesignsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7a8c;
    box-shadow: 0 0 0 3px rgba(47, 122, 140, 0.15);
}

.progdesignsim-container select option {
    background-color: #ffffff;
    color: #21303d;
}

.progdesignsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b3531a;
}

.progdesignsim-range-readout,
.progdesignsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1d4e6a;
    margin-top: 4px;
}

.progdesignsim-range-readout span,
.progdesignsim-alloc-readout span {
    color: #b3531a;
    font-weight: 800;
}

.progdesignsim-range-readout span:first-child,
.progdesignsim-alloc-readout span:first-child {
    color: #1d4e6a;
    font-weight: 700;
}

.progdesignsim-hint {
    font-size: 0.8rem;
    color: #7d8c96;
    margin-top: 4px;
    line-height: 1.4;
}

.progdesignsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.progdesignsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f3ea;
    border: 1px solid #e7e0d0;
    border-radius: 9px;
    padding: 8px 12px;
}

.progdesignsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #21303d;
}

.progdesignsim-alloc-row input[type="number"] {
    width: 100px;
    flex: 0 0 100px;
}

.progdesignsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.progdesignsim-container .btn-primary {
    background: linear-gradient(135deg, #b3531a 0%, #d4793a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(179, 83, 26, 0.28);
}

.progdesignsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.progdesignsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdd7dd;
    color: #6b7a85;
}

.progdesignsim-coach {
    background: #122a44;
    color: #eef6f9;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(18, 42, 68, 0.22);
}

.progdesignsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd9a8;
    margin-bottom: 8px;
}

.progdesignsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.progdesignsim-coach-body strong { color: #ffd9a8; }
.progdesignsim-coach-body em { color: #ffc1ad; font-style: italic; }

.progdesignsim-history,
.progdesignsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0dccf;
    box-shadow: 0 4px 14px rgba(18, 42, 68, 0.06);
}

.progdesignsim-history h3,
.progdesignsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #122a44;
}

.progdesignsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #21303d;
}

.progdesignsim-container table#usfHistoryTable th {
    background: #f1ece0;
    color: #122a44;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e4ddcd;
}

.progdesignsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece2;
}

.progdesignsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f0;
}

.progdesignsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .progdesignsim-container {
        padding: 14px;
    }
    .progdesignsim-header h1 {
        font-size: 1.7rem;
    }
    .progdesignsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .progdesignsim-value {
        font-size: 2rem;
    }
    .progdesignsim-clock {
        margin-left: 0;
    }
    .progdesignsim-period-counter {
        font-size: 0.88rem;
    }
    .progdesignsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .progdesignsim-alloc-row {
        flex-wrap: wrap;
    }
    .progdesignsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .progdesignsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================================
   v1.1.0 — Completion debrief (formatCompletionMessage). Append-only, namespaced
   .pg-cm-* so it cannot collide with the base engine or the view. Bayfront palette
   (deep navy + rust + teal), matched to the header and chart series.
   ============================================================================ */
.pg-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #21303d; text-align: left; max-width: 760px; margin: 0 auto; }
.pg-cm-incomplete { text-align: center; color: #4d5c68; font-size: 1rem; padding: 18px; }
.pg-cm-head { display: flex; flex-wrap: wrap; align-items: stretch; gap: 16px; padding: 20px 22px; margin-bottom: 16px;
    background: linear-gradient(135deg, #122a44 0%, #1d4e6a 60%, #2f7a8c 100%); color: #eef6f9; border-radius: 16px;
    border: 1px solid #16354f; box-shadow: 0 10px 28px rgba(18, 42, 68, 0.30); }
.pg-cm-score { text-align: center; padding-right: 20px; border-right: 1px solid rgba(238,246,249,0.22); }
.pg-cm-score-num { font-size: 3.1rem; font-weight: 800; line-height: 1; color: #ffd9a8; }
.pg-cm-score-den { font-size: 1.1rem; font-weight: 600; color: #cdd7dd; margin-left: 2px; }
.pg-cm-score-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; margin-top: 8px; color: #a9bcc7; }
.pg-cm-verdict { display: flex; flex-direction: column; justify-content: center; flex: 1 1 auto; min-width: 180px; }
.pg-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; color: #7fd0c0; font-weight: 700; }
.pg-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; letter-spacing: -0.3px; color: #ffffff; margin-top: 4px; }
.pg-cm-section { margin: 0 0 16px; }
.pg-cm-section-h { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1.1px; font-weight: 700; color: #4d5c68; margin-bottom: 9px; }
.pg-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.pg-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.82rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.pg-cm-chip .pg-cm-ico { font-weight: 800; }
.pg-cm-ok { background: #e4f1ea; color: #1f6b45; border-color: #b6dcc4; }
.pg-cm-no { background: #f7e7e2; color: #a2401b; border-color: #e6c3b3; }
.pg-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }
.pg-cm-kpi { background: #eef6f9; border: 1px solid #cdd7dd; border-radius: 12px; padding: 12px 14px; text-align: center; }
.pg-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #1d4e6a; line-height: 1.1; }
.pg-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #21303d; margin-top: 4px; }
.pg-cm-kpi-sub { font-size: 0.68rem; color: #5c6b76; margin-top: 3px; }
.pg-cm-insights { margin: 0; padding-left: 20px; }
.pg-cm-insights li { font-size: 0.9rem; line-height: 1.5; color: #2b3a45; margin-bottom: 7px; }
@media (max-width: 520px) { .pg-cm-score { border-right: none; border-bottom: 1px solid rgba(238,246,249,0.22); padding-right: 0; padding-bottom: 14px; } .pg-cm-head { flex-direction: column; } }

