(function() {
    'use strict';

    class ProgramDesignerAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Program Designer`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.BUDGET_CAP = 180;        // USD 180k development-cost cap (incl. marketing reserve)
            this.BREAK_EVEN = 60;         // 60 paid seats across two cohorts
            this.DEV_COST_USD = 180000;   // break-even denominator (full cap)

            // Segment willingness-to-pay anchors (USD) and feasible supply (seats / 2 cohorts).
            this.SEG = {
                changer:   { wtp: 3000, supply: 80, label: `changer` },
                corporate: { wtp: 4000, supply: 40, label: `corporate` },
                midmgr:    { wtp: 2100, supply: 120, label: `midmgr` },
                everyone:  { wtp: 2200, supply: 90, label: `everyone` }
            };

            // Concept-correct play.
            this.TRUE_SEGMENT = `changer`;
            this.TRUE_FORMAT = `live`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fit: 20,
                    enroll: 0,
                    margin: 25,
                    renewal: 20,
                    budgetUsed: 0,
                    budgetOver: false,
                    breakEvenSeats: 0,
                    cmPerLearner: 0,
                    capBreached: false,
                    underEnrolled: false,
                    fitHistory: [20],
                    enrollHistory: [0],
                    marginHistory: [25],
                    renewalHistory: [20],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed a MIDDLING / neutral mix — never the textbook-correct play.
                state.decisions = {
                    segment: `midmgr`,
                    wtp: `costplus`,
                    rigor: 50,
                    format: `selfpaced`,
                    designSpend: 40,
                    mediaSpend: 40,
                    smeSpend: 30,
                    marketingSpend: 25,
                    price: 2400,
                    varcost: 600,
                    tier: `no`,
                    funnel: 50,
                    defend: `margin`,
                    contingency: `runanyway`,
                    scorecard: `revenue`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const seg = document.getElementById(`segmentInput`);
                const wtp = document.getElementById(`wtpInput`);
                const rig = document.getElementById(`rigorInput`);
                if (seg) decisions.segment = seg.value;
                if (wtp) decisions.wtp = wtp.value;
                if (rig) decisions.rigor = parseInt(rig.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const fmt = document.getElementById(`formatInput`);
                if (fmt) decisions.format = fmt.value;
                const ds = document.getElementById(`designSpendInput`);
                const md = document.getElementById(`mediaSpendInput`);
                const sm = document.getElementById(`smeSpendInput`);
                const mk = document.getElementById(`marketingSpendInput`);
                if (ds) decisions.designSpend = parseFloat(ds.value);
                if (md) decisions.mediaSpend = parseFloat(md.value);
                if (sm) decisions.smeSpend = parseFloat(sm.value);
                if (mk) decisions.marketingSpend = parseFloat(mk.value);
                const parts = [decisions.designSpend, decisions.mediaSpend, decisions.smeSpend, decisions.marketingSpend];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_budget_negative`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`priceInput`);
                const vc = document.getElementById(`varcostInput`);
                const ti = document.getElementById(`tierInput`);
                const fn = document.getElementById(`funnelInput`);
                if (pr) decisions.price = parseFloat(pr.value);
                if (vc) decisions.varcost = parseFloat(vc.value);
                if (ti) decisions.tier = ti.value;
                if (fn) decisions.funnel = parseInt(fn.value, 10);
                if (!Number.isFinite(decisions.price) || decisions.price <= 0) {
                    warn(`warn_price_positive`); return false;
                }
                if (!Number.isFinite(decisions.varcost) || decisions.varcost < 0) {
                    warn(`warn_varcost_negative`); return false;
                }
                if (decisions.varcost >= decisions.price) {
                    warn(`warn_cm_nonpositive`); return false;
                }
                if (!Number.isFinite(decisions.funnel) || decisions.funnel < 0 || decisions.funnel > 100) {
                    warn(`warn_funnel_range`); return false;
                }
            } else if (round === 4) {
                const de = document.getElementById(`defendInput`);
                const co = document.getElementById(`contingencyInput`);
                const sc = document.getElementById(`scorecardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (de) decisions.defend = de.value;
                if (co) decisions.contingency = co.value;
                if (sc) decisions.scorecard = sc.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fitDelta = 0, marginDelta = 0, renewalDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            const seg = this.SEG[d.segment] || this.SEG.midmgr;

            if (round === 1) {
                // Segment-first design (Common Error 1: a course for everyone).
                switch (d.segment) {
                    case `changer`:
                        fitDelta += 18; renewalDelta += 6; marginDelta += 5; coachKey = `coach_r1_changer`; break;
                    case `corporate`:
                        fitDelta += 9; marginDelta += 6; renewalDelta += 2; coachKey = `coach_r1_corporate`; break;
                    case `midmgr`:
                        fitDelta += 4; marginDelta -= 4; renewalDelta -= 2; coachKey = `coach_r1_midmgr`; break;
                    case `everyone`:
                        fitDelta -= 12; marginDelta -= 6; renewalDelta -= 4; coachKey = `coach_r1_everyone`; break;
                }

                // Value-based vs cost-plus pricing (Common Error 4).
                if (d.wtp === `value`) {
                    marginDelta += 10; fitDelta += 6;
                    if (d.segment === this.TRUE_SEGMENT) coachKey = `coach_r1_segfirst`;
                } else {
                    marginDelta -= 8; fitDelta -= 4; coachKey = `coach_r1_costplus`;
                }

                // Demand-sizing rigor: can the segment actually supply 60 seats?
                if (d.rigor >= 60) { fitDelta += 6; marginDelta += 2; }
                else if (d.rigor <= 25) { fitDelta -= 6; coachKey = `coach_r1_norigor`; }

                summaryKey = (d.segment === this.TRUE_SEGMENT && d.wtp === `value`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Delivery-format economics (Common Errors 2 & 3) + the binding cap.
                const buildSpend = (d.designSpend || 0) + (d.mediaSpend || 0) + (d.smeSpend || 0);
                spend = buildSpend + (d.marketingSpend || 0);

                // Build-cost floor each format genuinely needs to be credible.
                let buildFloor = 70;
                switch (d.format) {
                    case `live`:
                        buildFloor = 120; fitDelta += 14; renewalDelta += 12; coachKey = `coach_r2_live`; break;
                    case `selfpaced`:
                        buildFloor = 70; fitDelta += 5; renewalDelta -= 12; marginDelta += 4; coachKey = `coach_r2_selfpaced`; break;
                    case `inperson`:
                        buildFloor = 150; fitDelta += 10; renewalDelta += 12; coachKey = `coach_r2_inperson`; break;
                }

                // Under-funding the build the chosen format requires hurts fit & renewal.
                if (buildSpend < buildFloor) {
                    const shortfall = buildFloor - buildSpend;
                    fitDelta -= Math.min(14, Math.round(shortfall / 5));
                    renewalDelta -= Math.min(10, Math.round(shortfall / 8));
                    if (coachKey === `coach_default` || coachKey === `coach_r2_live`) coachKey = `coach_r2_underfund`;
                }

                // Marketing reserve is needed to fund acquisition for the funnel.
                if ((d.marketingSpend || 0) >= 20) { fitDelta += 3; }
                else { fitDelta -= 4; renewalDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r2_nomarketing`; }

                // The cost cap is BINDING — in-person + a real marketing reserve breaches it.
                if (spend > this.BUDGET_CAP) {
                    ds.capBreached = true; ds.budgetOver = true;
                    const over = spend - this.BUDGET_CAP;
                    marginDelta -= Math.min(20, 8 + Math.round(over / 3));
                    fitDelta -= 4;
                    coachKey = `coach_r2_overcap`;
                } else {
                    ds.budgetOver = false;
                }

                summaryKey = (d.format === this.TRUE_FORMAT && spend <= this.BUDGET_CAP && buildSpend >= buildFloor) ? `sum_r2_good`
                           : (spend > this.BUDGET_CAP ? `sum_r2_overcap` : `sum_r2_weak`);
            } else if (round === 3) {
                // Pricing for services + break-even (Common Errors 4 & 5).
                const price = d.price;
                const varcost = d.varcost;
                const cm = Math.max(1, price - varcost);
                ds.cmPerLearner = cm;
                ds.breakEvenSeats = Math.ceil(this.DEV_COST_USD / cm);

                // Price vs the chosen segment's willingness-to-pay.
                const wtp = seg.wtp;
                const ratio = price / wtp;             // 1.0 = right at WTP
                // A value-anchored price sits ~0.9–1.05 of WTP. Below leaves money on the table;
                // far above pushes required enrollment past what the segment can supply.
                let priceFitFactor;
                if (ratio <= 0.6) priceFitFactor = 0.45;        // cost-plus / underpriced
                else if (ratio <= 0.85) priceFitFactor = 0.75;
                else if (ratio <= 1.08) priceFitFactor = 1.0;   // value-anchored sweet spot
                else if (ratio <= 1.25) priceFitFactor = 0.7;
                else priceFitFactor = 0.4;                       // unfillable premium

                // Demand the funnel can convert from the addressable segment supply.
                const reach = 0.45 + 0.0055 * (d.funnel || 0);   // 0.45 .. 1.0
                let achievable = seg.supply * reach * priceFitFactor;
                // A corporate tier backfills enrollment for non-corporate primary segments.
                if (d.tier === `yes`) {
                    if (d.segment === `corporate`) achievable += 6;     // modest; corporate already the base
                    else achievable += 18;                              // real backfill of a thin public funnel
                }
                let enroll = Math.round(achievable);

                // The corporate primary segment is supply-capped at ~40 feasible seats.
                if (d.segment === `corporate` && d.tier !== `yes`) enroll = Math.min(enroll, seg.supply);

                ds.enroll = Math.max(0, enroll);

                // Margin health: CM strength AND whether break-even is at/under 60.
                if (cm >= 3000) marginDelta += 16;
                else if (cm >= 2400) marginDelta += 12;
                else if (cm >= 1800) marginDelta += 6;
                else if (cm >= 1200) marginDelta += 0;
                else marginDelta -= 8;

                if (ds.breakEvenSeats <= this.BREAK_EVEN) { marginDelta += 10; fitDelta += 4; coachKey = `coach_r3_breakeven`; }
                else if (ds.breakEvenSeats <= 75) { marginDelta += 2; coachKey = `coach_r3_tight`; }
                else { marginDelta -= 8; coachKey = `coach_r3_unrecoverable`; }

                // Reconcile price against supply (Common Error 5: unfillable price).
                if (priceFitFactor <= 0.45 && ratio > 1.25) { fitDelta -= 8; coachKey = `coach_r3_unfillable`; }
                else if (priceFitFactor <= 0.45) { fitDelta -= 6; coachKey = `coach_r3_underpriced`; }
                else if (priceFitFactor >= 1.0) { fitDelta += 8; renewalDelta += 2;
                    if (ds.enroll >= this.BREAK_EVEN && ds.breakEvenSeats <= this.BREAK_EVEN) coachKey = `coach_r3_clears`; }

                // Enrollment vs break-even drives the Enroll KPI narrative.
                if (ds.enroll < this.BREAK_EVEN) { fitDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_short` : coachKey; }

                summaryKey = (ds.enroll >= this.BREAK_EVEN && ds.breakEvenSeats <= this.BREAK_EVEN) ? `sum_r3_good`
                           : (ds.breakEvenSeats > 75 ? `sum_r3_unrecover` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the design + name a contingency (Common Errors 3 & 6).
                switch (d.defend) {
                    case `renewal`: renewalDelta += 10; fitDelta += 8; marginDelta += 2; coachKey = `coach_r4_renewal`; break;
                    case `margin`: renewalDelta -= 8; fitDelta -= 4; coachKey = `coach_r4_margin`; break;
                    case `prestige`: fitDelta -= 6; coachKey = `coach_r4_prestige`; break;
                }

                switch (d.contingency) {
                    case `backfill`: fitDelta += 8; marginDelta += 6; renewalDelta += 2; break;
                    case `runanyway`: marginDelta -= 6; fitDelta -= 2; coachKey = `coach_r4_runanyway`; break;
                    case `none`: marginDelta -= 12; fitDelta -= 8; ds.underEnrolled = true; coachKey = `coach_r4_nocontingency`; break;
                }

                switch (d.scorecard) {
                    case `full`: fitDelta += 8; renewalDelta += 6;
                        if (d.defend === `renewal` && d.contingency === `backfill`) coachKey = `coach_r4_boardready`; break;
                    case `revenue`: renewalDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_revenueonly` : coachKey; break;
                    case `enroll`: fitDelta -= 2; marginDelta -= 2; break;
                }

                fitDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.defend === `renewal` && d.contingency === `backfill` && d.scorecard === `full`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (budget only committed in round 2).
            if (round === 2) ds.budgetUsed = Math.round(spend);

            // KPIs move on their deltas.
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.margin = Math.max(0, Math.min(100, ds.margin + marginDelta));
            ds.renewal = Math.max(0, Math.min(100, ds.renewal + renewalDelta));

            ds.fitHistory.push(Math.round(ds.fit));
            ds.enrollHistory.push(Math.round(ds.enroll));
            ds.marginHistory.push(Math.round(ds.margin));
            ds.renewalHistory.push(Math.round(ds.renewal));

            if (round === this.ROUNDS.length && ds.enroll < this.BREAK_EVEN) ds.underEnrolled = true;

            // v1.1.0 fix — persist composite where Express grading/reporting reads it
            // (results_utils.php express_resolveDomainScore -> performance.overallScore, then top-level score).
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                score: composite,
                overallScore: composite,
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                enroll: Math.round(ds.enroll),
                margin: Math.round(ds.margin),
                marginDelta: Math.round(marginDelta),
                renewal: Math.round(ds.renewal),
                renewalDelta: Math.round(renewalDelta),
                breakEvenSeats: ds.breakEvenSeats,
                cmPerLearner: ds.cmPerLearner,
                budgetUsed: ds.budgetUsed,
                capBreached: ds.capBreached,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`fitDisplay`, `domainState.fit`, (v) => Math.round(Number(v)));
            uiManager.bind(`enrollDisplay`, `domainState.enroll`, (v) => {
                const card = document.querySelector(`.progdesignsim-card-enroll`);
                if (card) {
                    card.classList.toggle(`progdesignsim-enroll-target`, Math.round(Number(v)) >= this.BREAK_EVEN);
                    card.classList.toggle(`progdesignsim-enroll-fail`, Math.round(Number(v)) > 0 && Math.round(Number(v)) < this.BREAK_EVEN);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => Math.round(Number(v)));
            uiManager.bind(`renewalDisplay`, `domainState.renewal`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.progdesignsim-budget-bar`);
                if (card) card.classList.toggle(`progdesignsim-budget-bar-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return `$` + Math.round(Number(v)) + `k / $180k`;
            });

            const self = this;

            // Rigor slider readout.
            const rig = document.getElementById(`rigorInput`);
            const rigReadout = document.getElementById(`rigorReadout`);
            if (rig && rigReadout) {
                rigReadout.textContent = rig.value;
                rig.addEventListener(`input`, function() { rigReadout.textContent = rig.value; });
            }

            // Funnel slider readout.
            const fn = document.getElementById(`funnelInput`);
            const fnReadout = document.getElementById(`funnelReadout`);
            if (fn && fnReadout) {
                fnReadout.textContent = fn.value;
                fn.addEventListener(`input`, function() { fnReadout.textContent = fn.value; });
            }

            // Live development-budget total.
            const budgetIds = [`designSpendInput`, `mediaSpendInput`, `smeSpendInput`, `marketingSpendInput`];
            const budgetReadout = document.getElementById(`budgetReadout`);
            const recompute = function() {
                let total = 0;
                budgetIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (budgetReadout) budgetReadout.textContent = total;
                const bar = document.querySelector(`#round2Panel .progdesignsim-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP) ? `#c0392b` : ``;
            };
            budgetIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();

            // Live contribution-margin & break-even readout.
            const priceEl = document.getElementById(`priceInput`);
            const varEl = document.getElementById(`varcostInput`);
            const cmReadout = document.getElementById(`cmReadout`);
            const beReadout = document.getElementById(`beReadout`);
            const recomputeCM = function() {
                const price = parseFloat(priceEl ? priceEl.value : 0) || 0;
                const varc = parseFloat(varEl ? varEl.value : 0) || 0;
                const cm = price - varc;
                if (cmReadout) cmReadout.textContent = `$` + (cm > 0 ? cm.toLocaleString(`en-US`) : `0`);
                if (beReadout) beReadout.textContent = (cm > 0) ? Math.ceil(self.DEV_COST_USD / cm) : `—`;
            };
            if (priceEl) priceEl.addEventListener(`input`, recomputeCM);
            if (varEl) varEl.addEventListener(`input`, recomputeCM);
            recomputeCM();
        }

