        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.fitHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                programChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.fitHistory },
                        { data: ds.marginHistory },
                        { data: ds.renewalHistory },
                        { data: ds.enrollHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const fit = Math.round(ds.fit);
            const margin = Math.round(ds.margin);
            const renewal = Math.round(ds.renewal);
            const enroll = Math.round(ds.enroll);
            return Math.round(
                fit * 0.30 + margin * 0.25 + renewal * 0.25 + Math.min(100, (enroll / this.BREAK_EVEN) * 100) * 0.20
            );
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fit = Math.round(ds.fit);
            const margin = Math.round(ds.margin);
            const renewal = Math.round(ds.renewal);
            const enroll = Math.round(ds.enroll);

            const clearsBreakEven = enroll >= this.BREAK_EVEN && ds.breakEvenSeats <= this.BREAK_EVEN && !ds.capBreached;
            const strongDesign = fit >= 60 && renewal >= 55 && margin >= 55;
            const composite = this._composite(ds);

            // v1.1.0 fix — tier labels were hardcoded English; now i18n-keyed (localized es).
            let tierKey = `grade_killed`;
            if (clearsBreakEven && strongDesign && composite >= 72) tierKey = `grade_selfsustaining`;
            else if (clearsBreakEven && strongDesign) tierKey = `grade_approved`;
            else if (clearsBreakEven) tierKey = `grade_fragile`;
            else if (ds.capBreached) tierKey = `grade_overcap`;
            else if (enroll > 0 && enroll >= this.BREAK_EVEN * 0.6) tierKey = `grade_underenrolled`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (clearsBreakEven && strongDesign) insights.push(window.mySimulation.t(`insight_approved`));
            else if (clearsBreakEven) insights.push(window.mySimulation.t(`insight_fragile`));
            else if (ds.capBreached) insights.push(window.mySimulation.t(`insight_overcap`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (renewal < 45) insights.push(window.mySimulation.t(`insight_renewal`));
            if (margin < 45) insights.push(window.mySimulation.t(`insight_margin`));
            if (ds.breakEvenSeats > this.BREAK_EVEN) insights.push(window.mySimulation.t(`insight_breakeven`));
            if (clearsBreakEven && strongDesign && renewal >= 60) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                fit: fit,
                margin: margin,
                renewal: renewal,
                enroll: enroll,
                breakEvenSeats: ds.breakEvenSeats,
                clearsBreakEven: clearsBreakEven,
                composite: composite,
                performance: performance,
                performanceKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="pg-cm"><p class="pg-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="pg-cm-chip ` + (ok ? `pg-cm-ok` : `pg-cm-no`) + `">` +
                `<span class="pg-cm-ico">` + (ok ? `\u2713` : `\u2715`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="pg-cm-kpi"><div class="pg-cm-kpi-val">` + val +
                `</div><div class="pg-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="pg-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const fOk = s.fit >= 60, mOk = s.margin >= 55, rOk = s.renewal >= 55, beOk = !!s.clearsBreakEven;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="pg-cm">` +
  `<div class="pg-cm-head">` +
    `<div class="pg-cm-score"><div class="pg-cm-score-num">` + Math.round(s.composite) +
       `<span class="pg-cm-score-den">/100</span></div>` +
       `<div class="pg-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="pg-cm-verdict"><div class="pg-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="pg-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="pg-cm-section"><div class="pg-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="pg-cm-chips">` + chip(fOk, t(`cm_t_fit`)) + chip(mOk, t(`cm_t_margin`)) +
      chip(rOk, t(`cm_t_renewal`)) + chip(beOk, t(`cm_t_breakeven`)) + `</div></div>` +
  `<div class="pg-cm-section"><div class="pg-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="pg-cm-kpis">` +
      kpi(t(`fit_label`), Math.round(s.fit), t(`fit_sub`)) +
      kpi(t(`margin_label`), Math.round(s.margin), t(`margin_sub`)) +
      kpi(t(`renewal_label`), Math.round(s.renewal), t(`renewal_sub`)) +
      kpi(t(`enroll_label`), Math.round(s.enroll), t(`enroll_sub`)) +
    `</div></div>` +
  (insights ? `<div class="pg-cm-section"><div class="pg-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="pg-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.capBreached) return window.mySimulation.t(`hint_overcap`);
            if (ds.breakEvenSeats > 75 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_breakeven`);
            if (ds.renewal < 35) return window.mySimulation.t(`hint_renewal`);
            if (state.currentPeriod >= 3 && ds.enroll < this.BREAK_EVEN) return window.mySimulation.t(`hint_enroll`);
            if (ds.enroll >= this.BREAK_EVEN && ds.fit >= 60 && ds.renewal >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

